'use client';

import type { ExtendConfig, Path } from 'platejs';

import { TextApi } from 'platejs';
import {
  type BaseCommentConfig,
  BaseCommentPlugin,
  getDraftCommentKey,
} from '@platejs/comment';
import { toPlatePlugin } from 'platejs/react';

import { CommentLeaf } from '@/registry/ui/comment-node';
import { getDiscussionClickTarget } from './discussion-kit';

type CommentConfig = ExtendConfig<
  BaseCommentConfig,
  {
    activeId: string | null;
    commentingBlock: Path | null;
    hoverId: string | null;
  }
>;

export const commentPlugin = toPlatePlugin<CommentConfig>(BaseCommentPlugin, {
  handlers: {
    onClick: ({ api, event, setOption, type }) => {
      const activeTarget = getDiscussionClickTarget({
        selector: `.plite-${type}`,
        target: event.target,
      });

      if (!activeTarget) {
        setOption('activeId', null);
        return;
      }

      const commentEntry = api.comment?.node();

      setOption(
        'activeId',
        commentEntry ? (api.comment?.nodeId(commentEntry[0]) ?? null) : null
      );
    },
  },
  options: {
    activeId: null,
    commentingBlock: null,
    hoverId: null,
  },
})
  .extendTx(({ editor, setOption, type }) => (tx) => ({
    setDraft: (options = {}) => {
      const commentingBlock = editor.selection?.focus.path.slice(0, 1) ?? null;

      if (editor.api.isCollapsed()) {
        const blockEntry = editor.api.block();

        if (blockEntry) {
          tx.selection.set(blockEntry[1]);
        }
      }

      tx.nodes.set(
        {
          [getDraftCommentKey()]: true,
          [type]: true,
        },
        { match: TextApi.isText, split: true, ...options }
      );

      tx.selection.collapse();
      setOption('activeId', getDraftCommentKey());
      setOption('commentingBlock', commentingBlock);
    },
  }))
  .configure({
    node: { component: CommentLeaf },
    shortcuts: {
      setDraft: { keys: 'mod+shift+m' },
    },
  });

export const CommentKit = [commentPlugin];
